@Test public void normaliseWhiteSpace_1_oe() {
    Object a = normaliseWhitespace("    \r \n \r\n");
    assertEquals(" ", a);
    }

mut_method_definition:
public static String normaliseWhitespace(String string) {
        StringBuilder sb = StringUtil.borrowBuilder();
