public void shouldCorrectCharsetForDuplicateCharsetString_1_oe() {
    Object a = DataUtil.getCharsetFromContentType("text/html; charset=charset=iso-8859-1");
    assertEquals("iso-8859-1", a);
}

mut_method_definition:
static @Nullable String getCharsetFromContentType(@Nullable String contentType) {
        if (contentType == null) return null;
        Matcher m = charsetPattern.matcher(contentType);
        if (m.find()) {
            String charset = m.group(1).trim();
            charset = charset.replace("charset=", "");
            return validateCharset(charset);
        }
        return null;
    }

